def validate_catalog(catalog: Mapping[str, Mapping[str, str]] = TEXT) -> None:
    """Fail fast if a UI key is missing either supported language."""
    for key, values in catalog.items():
        if set(values) != set(LANGUAGES) or not all(str(value).strip() for value in values.values()):
            raise ValueError(f"Incomplete translation for {key}")


def t(key: str, language: str = ENGLISH, /, **values: object) -> str:
    """Get a translated UI string and safely interpolate its dynamic values."""
    try:
        template = TEXT[key][language if language in LANGUAGES else ENGLISH]
    except KeyError as exc:
        raise KeyError(f"Unknown translation key: {key}") from exc
    return template.format(**values)


validate_catalog()
